const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const employeeId = String(claims.sub).trim();
const webhookNode = $('Webhook - POST /leave-apply').first().json || {};
const body = webhookNode.body || {};

const leaveType = (body.leaveType || 'CASUAL').toUpperCase().trim();
const validTypes = ['CASUAL', 'SICK'];
if (!validTypes.includes(leaveType)) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: `Invalid leave type '${leaveType}'. Allowed: CASUAL, SICK.`
    }
  }];
}

const durationType = (body.durationType || 'FULL_DAY').toUpperCase().trim();
const validDurations = ['FULL_DAY', 'FIRST_HALF', 'SECOND_HALF'];
if (!validDurations.includes(durationType)) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: `Invalid duration type '${durationType}'. Allowed: FULL_DAY, FIRST_HALF, SECOND_HALF.`
    }
  }];
}

const startDate = String(body.startDate || '').trim();
if (!startDate || !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: "Start date is required in YYYY-MM-DD format."
    }
  }];
}

// 1. Check if start date is a Sunday
const [sy, sm, sd] = startDate.split('-').map(Number);
const startDayOfWeek = new Date(sy, sm - 1, sd).getDay();

let effectiveEndDate = startDate;
let daysCount = 1;

if (durationType === 'FIRST_HALF' || durationType === 'SECOND_HALF') {
  if (startDayOfWeek === 0) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "Sundays are regular weekly offs. You cannot apply for a leave on Sunday."
      }
    }];
  }
  daysCount = 0.5;
  effectiveEndDate = startDate;
} else {
  const rawEnd = String(body.endDate || '').trim();
  effectiveEndDate = (rawEnd && /^\d{4}-\d{2}-\d{2}$/.test(rawEnd)) ? rawEnd : startDate;
  if (effectiveEndDate < startDate) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "End date cannot be earlier than start date."
      }
    }];
  }

  const [ey, em, ed] = effectiveEndDate.split('-').map(Number);
  const endDayOfWeek = new Date(ey, em - 1, ed).getDay();

  if (startDayOfWeek === 0 && startDate === effectiveEndDate) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "Sundays are regular weekly offs. You cannot apply for a leave on Sunday."
      }
    }];
  }

  // Count strictly office working days (Mon-Sat). Sundays are regular weekly offs and NOT deducted from leaves!
  let workingDaysCount = 0;
  const cur = new Date(sy, sm - 1, sd);
  const end = new Date(ey, em - 1, ed);

  while (cur <= end) {
    if (cur.getDay() !== 0) { // Mon-Sat are office working days
      workingDaysCount++;
    }
    cur.setDate(cur.getDate() + 1);
  }

  if (workingDaysCount === 0) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "Selected leave period falls entirely on Sundays (weekly off). No leave deduction is needed."
      }
    }];
  }

  daysCount = workingDaysCount;
}

const reason = String(body.reason || '').trim();
if (!reason) {
  return [{
    json: {
      valid: false,
      statusCode: 400,
      error: "Please provide a reason for the leave request."
    }
  }];
}

const ackWhatsapp = body.whatsappNoticeAcknowledged !== false;
const leaveId = `lev-${Date.now()}-${employeeId}`;
const notifId = `notif-${Date.now()}-${employeeId}`;

return [{
  json: {
    valid: true,
    employeeId: employeeId,
    leaveId: leaveId,
    notifId: notifId,
    leaveType: leaveType,
    durationType: durationType,
    startDate: startDate,
    effectiveEndDate: effectiveEndDate,
    daysCount: daysCount,
    reason: reason,
    escapedReason: reason.replace(/'/g, "''"),
    whatsappNoticeAcknowledged: ackWhatsapp
  }
}];

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};
const req = data.leave_request || {};
const bal = data.current_balance || {};

if (!req.id) {
  return [{
    json: {
      success: false,
      statusCode: 500,
      error: "Failed to record leave request in database."
    }
  }];
}

const avail = parseFloat(bal.available || '0');
const requested = parseFloat(req.days_count || '0');
const applicantName = data.applicant_name || req.employee_id || 'Staff Member';

// Prepare Expo push messages for active admins
const rawTokens = Array.isArray(data.admin_tokens) ? data.admin_tokens : [];
const validTokens = rawTokens.filter(t => typeof t === 'string' && t.trim().length > 0);

const pushMessages = validTokens.map(token => ({
  to: token.trim(),
  sound: 'default',
  title: `New Leave Request - ${applicantName}`,
  body: `${applicantName} applied for ${requested} day(s) ${req.leave_type} leave (${req.start_date} to ${req.end_date}). Reason: ${req.reason || 'No reason'}`,
  priority: 'high',
  channelId: 'default',
  data: {
    type: 'LEAVE_APPLICATION',
    leaveId: req.id,
    employeeId: req.employee_id,
    targetScreen: '/(tabs)/approvals'
  }
}));

return [{
  json: {
    success: true,
    statusCode: 200,
    message: "Leave request submitted successfully. Pending admin review and WhatsApp notice.",
    request: {
      id: req.id,
      employeeId: req.employee_id,
      leaveType: req.leave_type,
      durationType: req.duration_type,
      startDate: req.start_date,
      endDate: req.end_date,
      daysCount: requested,
      reason: req.reason,
      status: req.status || 'PENDING',
      appliedOn: req.applied_on,
      whatsappNoticeAcknowledged: req.whatsapp_notice_acknowledged,
      comments: req.comments,
      createdAt: req.created_at
    },
    balance: {
      leaveType: req.leave_type,
      total: parseFloat(bal.total || '0'),
      used: parseFloat(bal.used || '0'),
      available: avail,
      projectedRemaining: Math.max(0, avail - requested)
    },
    hasPushMessages: pushMessages.length > 0,
    pushMessages: pushMessages
  }
}];

